def tracy_widom_cdf(s):
    """Cumulative distribution function of the Tracy-Widom (TW1) distribution."""
    s = np.asarray(s, dtype=float)
    res = np.interp(s, _S_GRID, _F1_TABLE, left=0.0, right=1.0)
    return res.item() if s.ndim == 0 else res


def tracy_widom_ppf(q):
    """Percent point function of the Tracy-Widom (TW1) distribution."""
    q = np.asarray(q, dtype=float)
    if np.any((q < 0.0) | (q > 1.0)):
        raise ValueError("Quantile q must be between 0 and 1.")

    res = np.interp(q, _F1_TABLE, _S_GRID)
    return res.item() if q.ndim == 0 else res
